/* @lc app=leetcode id=1786 lang=kotlin */ class Solution { fun countRestrictedPaths(n: Int, edges: Array<IntArray>): Int = edges.flatMap { (a, b, w) -> listOf(a to (b to w), b to (a to w)) }.groupBy({ it.first }, { it.second }).let { g -> LongArray(n + 1) { Long.MAX_VALUE }.also { it[n] = 0 }.let { d -> java.util.PriorityQueue<Pair<Long, Int>>(compareBy<Pair<Long, Int>> { it.first }).also { it.add(0L to n) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> g[u].orEmpty().filter { (v, w) -> c + w < d[v] }.forEach { (v, w) -> pq.add(c + w to v).also { d[v] = c + w } } }.let { LongArray(n + 1).also { it[n] = 1 }.let { ways -> (1..n).sortedBy { d[it] }.forEach { u -> if (u != n) ways[u] = g[u].orEmpty().filter { (v, _) -> d[v] < d[u] }.sumOf { (v, _) -> ways[v] } % 1_000_000_007 }.let { ways[1].toInt() } } } } } } }